from typing import List


class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        if k * 2 > len(s):
            return 0
        count = [0] * 26
        left = 0
        total = 0
        for ch in s:
            idx = ord(ch) - 97
            count[idx] += 1
            while count[idx] >= k:
                count[ord(s[left]) - 97] -= 1
                left += 1
            total += left
        return total

from typing import List


class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        if len(set(s)) == 1:
            return (len(s) - k) * (len(s) - k + 1) // 2
        count = [0] * 26
        left = 0
        total = 0
        for ch in s:
            idx = ord(ch) - 97
            count[idx] += 1
            while count[idx] >= k:
                count[ord(s[left]) - 97] -= 1
                left += 1
            total += left
        return total
